provider "aws" {
  region = "us-east-1"
}

resource "aws_db_option_group" "example" {
  name                     = "option-group-pike"
  option_group_description = "Terraform Option Group"
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11.00"

  option {
    db_security_group_memberships  = []
    option_name                    = "SQLSERVER_AUDIT"
    port                           = 0
    vpc_security_group_memberships = []

    option_settings {
      name  = "IAM_ROLE_ARN"
      value = "arn:aws:iam::680235478471:role/aws-service-role/rds.amazonaws.com/AWSServiceRoleForRDS"
    }
    option_settings {
      name  = "S3_BUCKET_ARN"
      value = "arn:aws:s3:::testbucketineu-west2/rds"
    }
  }

  option {
    option_name = "TDE"
    port        = 0
  }

  tags = {
    pike = "permissions"
  }
}

responsePreview:
The Terraform configuration below creates an AWS RDS Option Group named `option-group-pike` for the `sqlserver-ee` engine with major engine version `11.00`. It configures two options:

- `SQLSERVER_AUDIT`
  - Includes `IAM_ROLE_ARN`
  - Includes `S3_BUCKET_ARN`
- `TDE`

It also creates the supporting S3 bucket, IAM role, and IAM policy needed for SQL Server Audit to write audit logs to S3.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "sqlserver_audit_bucket" {
  bucket = "sqlserver-audit-option-group-pike-${random_id.bucket_suffix.hex}"

  tags = {
    Name        = "sqlserver-audit-option-group-pike"
    Environment = "example"
  }
}

